"""The config loader (PL-01 and PL-03 step 1).

A run config is one TOML file per world and variant:

    world = "snake"
    variant = "default"
    budget = 200000
    device = "cpu"            # optional

    [methods.snake]           # one table per team
    method = "dqn"
    lr = 0.001                # any setting left out takes the method's default

    [check_settings.dqn]      # optional: settings for the method's check world only
    hidden = 16
"""

import tomllib
from collections.abc import Mapping, Sequence
from pathlib import Path
from typing import Any, Literal

from rllab.core.types import MethodConfig, Settings
from rllab.train.types import RunConfig

METHOD_DEFAULTS: Mapping[str, Settings] = {
    "dqn": {
        "lr": 0.001,
        "gamma": 0.99,
        "hidden": 64,
        "epsilon_start": 1.0,
        "epsilon_end": 0.05,
        "epsilon_decay_steps": 20000,
    },
    "ppo": {
        "lr": 0.0003,
        "gamma": 0.99,
        "hidden": 64,
        "rollout_steps": 2048,
        "init_log_std": -0.5,
    },
}
WORLD_VARIANTS: Mapping[str, tuple[str, ...]] = {
    "snake": ("default",),
    "fish": ("one", "local", "many"),
    "prey": ("default",),
}
TOP_KEYS = ("world", "variant", "budget", "device", "methods", "check_settings")


def load_run_configs(path: Path, seeds: Sequence[int]) -> list[RunConfig]:
    """One `RunConfig` per seed from the TOML at `path`, named `<stem>-s<seed>`."""
    with path.open("rb") as f:
        raw = tomllib.load(f)
    _reject_unknown(raw, TOP_KEYS, "config")
    world, variant = _world_variant(raw)
    methods = {team: _method_config(team, table) for team, table in raw["methods"].items()}
    check_settings = {
        method: _settings(method, table, f"check_settings.{method}")
        for method, table in raw.get("check_settings", {}).items()
    }
    return [
        RunConfig(
            name=f"{path.stem}-s{seed}",
            world=world,
            variant=variant,
            methods=methods,
            seed=seed,
            budget=raw["budget"],
            check_settings=check_settings,
            device=raw.get("device", "cpu"),
        )
        for seed in seeds
    ]


def _world_variant(raw: Mapping[str, Any]) -> tuple[str, str]:
    world: str = raw["world"]
    variant: str = raw["variant"]
    if world not in WORLD_VARIANTS:
        raise ValueError(f"unknown world {world!r}")
    if variant not in WORLD_VARIANTS[world]:
        raise ValueError(f"unknown variant {variant!r} of world {world!r}")
    return world, variant


def _method_config(team: str, table: Mapping[str, Any]) -> MethodConfig:
    method: Literal["dqn", "ppo"] = table["method"]
    settings = {key: value for key, value in table.items() if key != "method"}
    return MethodConfig(method, _settings(method, settings, f"methods.{team}"))


def _settings(method: str, given: Mapping[str, Any], where: str) -> Settings:
    """The method's defaults with `given` on top; check settings keep only what is given."""
    if method not in METHOD_DEFAULTS:
        raise ValueError(f"unknown method {method!r} in {where}")
    defaults = METHOD_DEFAULTS[method]
    _reject_unknown(given, tuple(defaults), where)
    if where.startswith("check_settings"):
        return dict(given)
    return {**defaults, **given}


def _reject_unknown(table: Mapping[str, Any], known: Sequence[str], where: str) -> None:
    unknown = [key for key in table if key not in known]
    if unknown:
        raise ValueError(f"unknown key {unknown[0]!r} in {where}")

